INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Controlling eine fortlaufende Aufgabe im Projektmanagement?', 2, '[{"text": "Ja", "correct": true, "because": "Überwacht während Durchführung"}, {"text": "Nein", "correct": false, "because": "Es ist keine Einzelphase"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt das Controlling?', 3, '[{"text": "Sicherstellung der Zielerreichung", "correct": true, "because": "Kontrolliert Fortschritt"}, {"text": "Planung neu erstellen", "correct": false, "because": "Planungsaufgabe"}, {"text": "Team direkt motivieren", "correct": false, "because": "Nebenaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Controlling vergleicht Ist- mit Soll-Zustand. b) Es erfolgt nur am Projektstart.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, fortlaufend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bereiche überwacht das Controlling?', 4, '[{"text": "Zeit", "correct": true, "because": "Prüft Einhaltung"}, {"text": "Unklare Annahmen", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Kosten", "correct": true, "because": "Sichert Budget"}, {"text": "Qualität", "correct": true, "because": "Überwacht Standards"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Controlling ohne Planung möglich?', 2, '[{"text": "Nein", "correct": true, "because": "Plan ist Vergleichsgrundlage"}, {"text": "Ja", "correct": false, "because": "Unrealistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode unterstützt das Controlling?', 3, '[{"text": "Statusberichte", "correct": true, "because": "Zeigen Fortschritt"}, {"text": "Keine Überwachung", "correct": false, "because": "Fehlt Kontrolle"}, {"text": "Spontane Checks", "correct": false, "because": "Unsystematisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Gilt Controlling nur für technische Projekte?', 2, '[{"text": "Nein", "correct": true, "because": "Für alle Projekte relevant"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt ist beim Controlling zentral?', 3, '[{"text": "Abweichungsanalyse", "correct": true, "because": "Erkennt Probleme"}, {"text": "Teamzusammensetzung", "correct": false, "because": "Planungsaspekt"}, {"text": "Kostenreduktion", "correct": false, "because": "Nebenaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Controlling steuert Maßnahmen bei Abweichungen. b) Es ist nur für Zeitmanagement.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, umfassender"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Controlling?', 3, '[{"text": "Probleme bleiben unentdeckt", "correct": true, "because": "Keine Überwachung"}, {"text": "Projekt wird effizienter", "correct": false, "because": "Eher Chaos"}, {"text": "Kosten sinken automatisch", "correct": false, "because": "Können steigen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Controlling ohne Dokumentation erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Nachweis fehlt"}, {"text": "Ja", "correct": false, "because": "Unpraktisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt eine Controlling-Aktivität?', 3, '[{"text": "Kosten mit Budget vergleichen", "correct": true, "because": "Konkret und real"}, {"text": "Irgendwas überprüfen", "correct": false, "because": "Zu vage"}, {"text": "Team soll schneller sein", "correct": false, "because": "Keine Kontrolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Controlling nur für den Projektleiter relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Team braucht Rückmeldung"}, {"text": "Ja", "correct": false, "because": "Projektweite Bedeutung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Daten werden im Controlling genutzt?', 4, '[{"text": "Fortschrittsberichte", "correct": true, "because": "Zeigen Ist-Zustand"}, {"text": "Unklare Schätzungen", "correct": false, "because": "Erschweren Analyse"}, {"text": "Kostenaufstellungen", "correct": true, "because": "Überwachen Budget"}, {"text": "Zeitaufzeichnungen", "correct": true, "because": "Vergleichen Plan"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss Controlling regelmäßig erfolgen?', 2, '[{"text": "Ja", "correct": true, "because": "Fortlaufende Überwachung"}, {"text": "Nein", "correct": false, "because": "Einmalig unzureichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt Controlling?', 3, '[{"text": "Projektziele absichern", "correct": true, "because": "Passt Kurs an"}, {"text": "Neue Planung erstellen", "correct": false, "because": "Planungsaufgabe"}, {"text": "Technische Lösung finden", "correct": false, "because": "Durchführungsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Controlling ohne Projektstrukturplan erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Struktur ist Basis"}, {"text": "Ja", "correct": false, "because": "Unstrukturiert unpraktisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erschwert das Controlling?', 3, '[{"text": "Ungenaue Daten", "correct": true, "because": "Verhindern Analyse"}, {"text": "Klarer Zeitplan", "correct": false, "because": "Fördert Kontrolle"}, {"text": "Gute Ressourcen", "correct": false, "because": "Unterstützen Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Controlling hilft bei Entscheidungen. b) Es ist nur für große Projekte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, breit anwendbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen des Controllings?', 3, '[{"text": "Frühzeitige Korrekturmaßnahmen", "correct": true, "because": "Verhindert Probleme"}, {"text": "Unklare Steuerung", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Anpassung", "correct": false, "because": "Fördert Flexibilität"}]');
